content.solution_code:
class Display {
  constructor(resolution) {
    this.resolution = resolution;
  }

  render(message) {
    return `Display (${this.resolution}): ${message}`;
  }
}

class Battery {
  constructor(capacityWh) {
    this.capacityWh = capacityWh;
    this.chargeLevel = 100; // Represents percentage
  }

  getLevel() {
    return this.chargeLevel;
  }
}

class SmartDevice {
  constructor(brand, display, battery) {
    this.brand = brand;
    this.display = display;
    this.battery = battery;
  }

  reportStatus() {
    const displayStatus = this.display.render("Ready.");
    const batteryLevel = this.battery.getLevel();
    return `MySmartDevice Status (Brand: ${this.brand}): ${displayStatus} Battery: ${batteryLevel}%`;
  }
}

